installation.script:
#!/bin/ash
apk add --no-cache curl tar go ca-certificates

cd /mnt/server
mkdir -p data

echo "[Installer] Downloading source code from GitHub..."
curl -sSL https://github.com/zhw1nq/r2-uploader-go/archive/refs/heads/${GIT_BRANCH}.tar.gz | tar -xz --strip-components=1

echo "[Installer] Building Go production binary..."
export GOPATH=/mnt/server/.go
export GOCACHE=/mnt/server/.cache
CGO_ENABLED=0 go build -ldflags="-s -w" -o ${SERVER_BINARY} ./cmd/server
chmod +x ${SERVER_BINARY}
rm -rf /mnt/server/.go /mnt/server/.cache

if [ ! -f .env ]; then
    cat << 'EOF' > .env
PORT=${SERVER_PORT}
R2_ACCOUNT_ID=${R2_ACCOUNT_ID}
R2_ACCESS_KEY_ID=${R2_ACCESS_KEY_ID}
R2_SECRET_ACCESS_KEY=${R2_SECRET_ACCESS_KEY}
R2_BUCKET_NAME=${R2_BUCKET_NAME}
R2_ROOT_FOLDER=${R2_ROOT_FOLDER}
R2_PUBLIC_DOMAIN=${R2_PUBLIC_DOMAIN}
APP_URL=${APP_URL}
ADMIN_KEY=${ADMIN_KEY}
SQLITE_PATH=data/data.db
KEY_PREFIX=sk_vhming_
EOF
fi

echo "-----------------------------------------"
echo "Installation & Build completed! Binary: ${SERVER_BINARY}"
echo "-----------------------------------------"
